class ECMemberScreen : Screen {
    @OptIn(ExperimentalVoyagerApi::class, KoinExperimentalAPI::class)
    @Composable
    override fun Content() {
        val vieModel: MainViewModel = koinViewModel<MainViewModel>()
        val sharedViewModel = navigatorViewModel { vieModel }
        ECMemberScreenContent(viewModel = sharedViewModel)
    }
}

@OptIn(ExperimentalMaterial3Api::class, KoinExperimentalAPI::class)
@Composable
fun ECMemberScreenContent(
    viewModel: MainViewModel = koinViewModel<MainViewModel>(),
) {
    viewModel.getECMemberList()
    val state = viewModel.state.collectAsState()
    val navigator = LocalNavigator.currentOrThrow

    var showBottomSheet by remember { mutableStateOf(false) }
    var currentUser: User? by remember { mutableStateOf(null) }

    val bottomSheetState = rememberModalBottomSheetState(
        skipPartiallyExpanded = true,
    )

    if (showBottomSheet) {
        AddECMemberBottomSheet(
            onCancelClicked = {
                showBottomSheet = false
                currentUser = null
            },
            onSaveClicked = { user ->
                showBottomSheet = false
                currentUser = null
                viewModel.addECMember(user)
                viewModel.addMember(user)
            },
            bottomSheetState = bottomSheetState,
            user = currentUser
        )
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Text(
                        text = "EC Members",
                        color = Color.White
                    )
                },
                navigationIcon = {
                    IconButton(
                        onClick = {
                            navigator.pop()
                        }
                    ) {
                        Icon(
                            imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                            contentDescription = "Back",
                            tint = Color.White
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = Color(0xFF1A9771)
                )
            )
        },
        bottomBar = {
            if (state.value.user?.accessLevel == AccessLevel.ADMIN) {
                Row(
                    modifier = Modifier.fillMaxWidth().padding(16.dp),
                ) {
                    Spacer(modifier = Modifier.weight(1f))
                    FloatingActionButton(
                        onClick = {
                            showBottomSheet = true
                        },
                        containerColor = Color(0xFF00DBA6)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Add,
                            tint = Color.White,
                            contentDescription = "Add"
                        )
                    }
                }
            }
        },
        containerColor = Color(0xFFFAF9F6)
    ) { paddingValues ->
        CircleBackground(2f, paddingValues)
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues),
            contentPadding = PaddingValues(vertical = 16.dp),
            userScrollEnabled = true,
        ) {
            if (state.value.ecMembers.isNotEmpty()) {
                items(state.value.ecMembers) { ecMember ->
                    ECMemberItem(
                        user = ecMember,
                        isEditable = state.value.user?.accessLevel == AccessLevel.ADMIN,
                        onEditClicked = { user ->
                            currentUser = user
                            showBottomSheet = true
                        }
                    )
                }
            } else {
                item {
                    Text(
                        modifier = Modifier.padding(horizontal = 16.dp).fillParentMaxSize(),
                        text = "No ec members found",
                        textAlign = TextAlign.Center,
                    )
                }
            }
        }
    }
}

@Composable
fun ECMemberItem(
    modifier: Modifier = Modifier,
    user: User,
    isEditable: Boolean,
    onEditClicked: (user: User) -> Unit = {}
) {
    var expanded by remember { mutableStateOf(false) }

    Card(
        modifier = modifier
            .fillMaxWidth()
            .animateContentSize(
                animationSpec = tween(
                    durationMillis = 300,
                    easing = LinearOutSlowInEasing
                )
            )
            .padding(horizontal = 16.dp, vertical = 4.dp),
        onClick = {
            expanded = !expanded
        },
        elevation = CardDefaults.cardElevation(
            defaultElevation = 8.dp
        )
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .background(MaterialTheme.colorScheme.surface)
                .padding(horizontal = 16.dp, vertical = 8.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth()
            ) {
                Text(
                    modifier = Modifier.weight(1f),
                    text = user.firstName + " " + user.lastName,
                    style = MaterialTheme.typography.titleMedium
                )
                Text(
                    text = user.accessLevel.name,
                    style = MaterialTheme.typography.bodyLarge
                )
            }

            Text(
                modifier = Modifier,
                text = user.position,
                style = MaterialTheme.typography.bodyLarge
            )

            if (expanded) {
                Spacer(modifier = Modifier.height(8.dp))
                Row(
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        modifier = Modifier.weight(1f),
                        text = "Login email: ",
                        style = MaterialTheme.typography.bodyLarge
                    )
                    Text(
                        text = user.loginEmail,
                        style = MaterialTheme.typography.bodyLarge
                    )
                }
                Spacer(modifier = Modifier.height(8.dp))
                Row(
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        modifier = Modifier.weight(1f),
                        text = "Contact email: ",
                        style = MaterialTheme.typography.bodyLarge
                    )
                    Text(
                        text = user.email,
                        style = MaterialTheme.typography.bodyLarge
                    )
                }
                Spacer(modifier = Modifier.height(8.dp))
                Row(
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        modifier = Modifier.weight(1f),
                        text = "Phone: ",
                        style = MaterialTheme.typography.bodyLarge
                    )
                    Text(
                        text = user.phone,
                        style = MaterialTheme.typography.bodyLarge
                    )
                }
                Spacer(modifier = Modifier.height(8.dp))
                Row(
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        modifier = Modifier.weight(1f),
                        text = "Starting Date: ",
                        style = MaterialTheme.typography.bodyLarge
                    )
                    Text(
                        text = user.startDate,
                        style = MaterialTheme.typography.bodyLarge
                    )
                }
                Spacer(modifier = Modifier.height(8.dp))
                Row(
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        modifier = Modifier.weight(1f),
                        text = "Status: ",
                        style = MaterialTheme.typography.bodyLarge
                    )
                    Text(
                        text = user.status.name,
                        style = MaterialTheme.typography.bodyLarge
                    )
                }

                if (isEditable) {
                    Spacer(modifier = Modifier.height(8.dp))
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.End
                    ) {
                        OutlinedButton(
                            onClick = {
                                onEditClicked(user)
                            },
                            shape = RoundedCornerShape(50),
                            colors = ButtonDefaults.outlinedButtonColors(
                                contentColor = Color(
                                    0xFF6750A4
                                )
                            ),
                            modifier = Modifier.padding(4.dp)
                        ) {
                            Text(
                                text = "Edit", style = TextStyle(
                                    fontSize = 14.sp,
                                    lineHeight = 20.sp,
                                    fontFamily = FontFamily.Default,
                                    fontWeight = FontWeight(500),
                                    color = Color(0xFF6750A4),
                                    textAlign = TextAlign.Center,
                                    letterSpacing = 0.1.sp
                                )
                            )
                        }
                    }
                }
            }
        }
    }
}
