import dev.gitlive.firebase.Firebase
import dev.gitlive.firebase.auth.auth
import kotlinx.coroutines.launch

class SettingsScreen : Screen {
    @Composable
    override fun Content() {
        SettingsScreenContent()
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SettingsScreenContent(
    authService: AuthService =  AuthServiceIml(Firebase.auth)
) {
    val navigator = LocalNavigator.currentOrThrow
    val scope = rememberCoroutineScope()
    var settingsError by remember { mutableStateOf("") }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Text(
                        text = "Settings",
                        color = Color.White
                    )
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = Color(0xFF1A9771)
                )
            )
        }
    ) { paddingValues ->
        CircleBackground(2f, paddingValues)
        Surface(
            modifier = Modifier.fillMaxSize().padding(top = paddingValues.calculateTopPadding()),
        ) {
            Column(
                modifier = Modifier.fillMaxSize().padding(16.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.Center
            ) {
                Spacer(modifier = Modifier.height(32.dp))
                if (settingsError.isNotEmpty()) {
                    Text(
                        text = settingsError,
                        color = MaterialTheme.colorScheme.error,
                        style = MaterialTheme.typography.bodyLarge
                    )
                    Spacer(modifier = Modifier.height(16.dp))
                }
                Button(
                    modifier = Modifier.fillMaxWidth(),
                    colors = ButtonDefaults.buttonColors(
                        containerColor = Color(0xFF00DBA6),
                    ),
                    onClick = {
                        scope.launch {
                            try {
                                authService.logout()
                                if (!authService.isLoggedIn) {
                                    navigator.parent?.push(LoginScreen())
                                } else {
                                    settingsError = "Logout failed"
                                }
                            } catch (e: Exception) {
                                settingsError = e.message ?: "Unknown error"
                            }
                        }
                    }
                ) {
                    Text("Logout")
                }
            }
        }
    }
}