class CompleteProfileScreen : Screen {
    @OptIn(ExperimentalVoyagerApi::class, KoinExperimentalAPI::class)
    @Composable
    override fun Content() {
        val vieModel: MainViewModel = koinViewModel<MainViewModel>()
        val sharedViewModel = navigatorViewModel { vieModel }
        CompleteProfileScreenContent(viewModel = sharedViewModel)
    }
}

@OptIn(ExperimentalMaterial3Api::class, KoinExperimentalAPI::class)
@Composable
fun CompleteProfileScreenContent(
    viewModel: MainViewModel = koinViewModel<MainViewModel>(),
) {
    val state = viewModel.state.collectAsState()
    val navigator = LocalNavigator.currentOrThrow

    var firstName by remember { mutableStateOf(state.value.user?.firstName ?: "") }
    var lastName by remember { mutableStateOf(state.value.user?.lastName ?: "") }
    var loginEmail by remember { mutableStateOf(state.value.user?.loginEmail ?: "") }
    var joiningDate by remember { mutableStateOf(state.value.user?.startDate ?: "") }
    var position by remember { mutableStateOf(state.value.user?.position ?: "") }
    var accessLevel by remember { mutableStateOf(state.value.user?.accessLevel?.name ?: "") }
    var countryOfResidence by remember {
        mutableStateOf(
            state.value.user?.countryOfResidence ?: ""
        )
    }
    var dob by remember { mutableStateOf(state.value.user?.dob ?: "") }
    var phone by remember { mutableStateOf(state.value.user?.phone ?: "") }
    var contactEmail by remember { mutableStateOf(state.value.user?.email ?: "") }

    var isError by remember { mutableStateOf(false) }

    var isCountryOfResidenceDialogVisible by remember { mutableStateOf(false) }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Text(
                        text = "Complete profile",
                        color = Color.White
                    )
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = Color(0xFF1A9771)
                ),
                navigationIcon = {
                    IconButton(onClick = { navigator.pop() }) {
                        Icon(
                            imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                            contentDescription = "Back",
                            tint = Color.White
                        )
                    }
                }
            )
        }
    ) { paddingValues ->

        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(top = paddingValues.calculateTopPadding())
                .padding(16.dp)
                .verticalScroll(rememberScrollState())
        ) {

            Text(
                text = "Complete your profile",
                style = MaterialTheme.typography.titleLarge,
                fontWeight = FontWeight(700),
                color = Color.Black,
                fontSize = 22.sp,
                fontFamily = FontFamily.Default,
                modifier = Modifier.align(Alignment.CenterHorizontally)
            )

            Spacer(modifier = Modifier.height(16.dp))

            OutlinedTextField(
                value = firstName,
                onValueChange = { firstName = it },
                label = { Text("First name") },
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.background),
                maxLines = 1,
                keyboardOptions = KeyboardOptions(
                    keyboardType = KeyboardType.Text,
                    imeAction = ImeAction.Done
                ),
                enabled = false,
            )

            Spacer(modifier = Modifier.height(8.dp))

            OutlinedTextField(
                value = lastName,
                onValueChange = { lastName = it },
                label = { Text("Last name") },
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.background),
                maxLines = 1,
                keyboardOptions = KeyboardOptions(
                    keyboardType = KeyboardType.Text,
                    imeAction = ImeAction.Done
                ),
                enabled = false,
            )

            Spacer(modifier = Modifier.height(8.dp))

            OutlinedTextField(
                value = dob,
                onValueChange = { dob = it },
                label = { Text("Date of birth (dd-mm-yyyy)") },
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.background),
                maxLines = 1,
                keyboardOptions = KeyboardOptions(
                    keyboardType = KeyboardType.Email,
                    imeAction = ImeAction.Done
                ),
                isError = isError && dob.isEmpty(),
            )

            Spacer(modifier = Modifier.height(8.dp))

            OutlinedTextField(
                value = countryOfResidence,
                onValueChange = { countryOfResidence = it },
                label = { Text("Country of residence") },
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.background)
                    .pointerInput(Unit) {
                        detectTapGestures(onTap = {
                            isCountryOfResidenceDialogVisible = true
                        })
                    },
                readOnly = true,
                maxLines = 1,
                colors = OutlinedTextFieldDefaults.colors(
                    disabledBorderColor = MaterialTheme.colorScheme.outline,
                    disabledContainerColor = MaterialTheme.colorScheme.background,
                    disabledTextColor = MaterialTheme.colorScheme.onBackground,
                    disabledLabelColor = MaterialTheme.colorScheme.onBackground,
                    disabledLeadingIconColor = MaterialTheme.colorScheme.onBackground,
                    disabledTrailingIconColor = MaterialTheme.colorScheme.onBackground,
                ),
                trailingIcon = {
                    IconButton(
                        onClick = { isCountryOfResidenceDialogVisible = true },
                        modifier = Modifier.padding(start = 8.dp)
                    ) {
                        Icon(Icons.Default.Add, contentDescription = "ADD")
                    }
                },
                isError = isError && countryOfResidence.isEmpty(),
            )

            Spacer(modifier = Modifier.height(8.dp))

            OutlinedTextField(
                value = loginEmail,
                onValueChange = { loginEmail = it },
                label = { Text("Login email") },
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.background),
                maxLines = 1,
                keyboardOptions = KeyboardOptions(
                    keyboardType = KeyboardType.Email,
                    imeAction = ImeAction.Done
                ),
                enabled = false,
            )

            Spacer(modifier = Modifier.height(8.dp))

            OutlinedTextField(
                value = phone,
                onValueChange = { phone = it },
                label = { Text("Phone") },
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.background),
                maxLines = 1,
                keyboardOptions = KeyboardOptions(
                    keyboardType = KeyboardType.Email,
                    imeAction = ImeAction.Done
                ),
                isError = isError && phone.isEmpty(),
            )

            Spacer(modifier = Modifier.height(8.dp))

            OutlinedTextField(
                value = contactEmail,
                onValueChange = { contactEmail = it },
                label = { Text("Contact email") },
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.background),
                maxLines = 1,
                keyboardOptions = KeyboardOptions(
                    keyboardType = KeyboardType.Email,
                    imeAction = ImeAction.Done
                ),
                isError = isError && contactEmail.isEmpty(),
            )

            Spacer(modifier = Modifier.height(8.dp))

            OutlinedTextField(
                value = joiningDate,
                onValueChange = { joiningDate = it },
                label = { Text("Joining date (dd-mm-yyyy)") },
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.background),
                maxLines = 1,
                keyboardOptions = KeyboardOptions(
                    keyboardType = KeyboardType.Text,
                    imeAction = ImeAction.Done
                ),
                enabled = false,
            )

            Spacer(modifier = Modifier.height(8.dp))

            OutlinedTextField(
                value = position,
                onValueChange = { position = it },
                label = { Text("Position") },
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.background),
                maxLines = 1,
                keyboardOptions = KeyboardOptions(
                    keyboardType = KeyboardType.Text,
                    imeAction = ImeAction.Done
                ),
                enabled = false,
            )

            Spacer(modifier = Modifier.height(8.dp))

            OutlinedTextField(
                value = accessLevel,
                onValueChange = { accessLevel = it },
                label = { Text("Access level") },
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.background),
                maxLines = 1,
                keyboardOptions = KeyboardOptions(
                    keyboardType = KeyboardType.Text,
                    imeAction = ImeAction.Done
                ),
                enabled = false,
            )

            if (isCountryOfResidenceDialogVisible) {
                AlertDialogListItems(
                    showDialog = true,
                    onDismissRequest = { isCountryOfResidenceDialogVisible = false },
                    title = "Select a country of residence",
                    items = Country.entries.map { it.name },
                    onItemSelected = { index, item ->
                        countryOfResidence = item
                        isCountryOfResidenceDialogVisible = false
                    },
                )
            }

            Spacer(modifier = Modifier.height(24.dp))

            Row(
                modifier = Modifier.fillMaxWidth(),
            ) {
                Button(
                    modifier = Modifier.weight(1f),
                    colors = ButtonDefaults.buttonColors(
                        containerColor = Color(0xFF00DBA6),
                    ),
                    onClick = {
                        if (
                            phone.isNotEmpty() && contactEmail.isNotEmpty() &&
                            countryOfResidence.isNotEmpty() && dob.isNotEmpty()
                        ) {
                            isError = false

                            val user = User(
                                loginEmail = loginEmail,
                                firstName = firstName,
                                lastName = lastName,
                                phone = phone,
                                email = contactEmail,
                                accessLevel = AccessLevel.getAccessLevel(
                                    accessLevel
                                ),
                                position = position,
                                status = Status.ACTIVE,
                                startDate = joiningDate,
                                countryOfResidence = countryOfResidence,
                                dob = dob,
                                firstimeRegistrationCode = "HUMANITY24",
                                memberId = state.value.user?.memberId
                            )
                            viewModel.addECMember(user)
                            viewModel.addMember(user)
                            navigator.pop()
                        } else {
                            isError = true
                        }
                    },
                ) {
                    Text(
                        text = "Save"
                    )
                }

                Spacer(modifier = Modifier.width(16.dp))

                Button(
                    modifier = Modifier.weight(1f),
                    colors = ButtonDefaults.buttonColors(
                        containerColor = Color(0xFF00DBA6),
                    ),
                    onClick = {
                        navigator.pop()
                    },
                ) {
                    Text(
                        text = "Cancel"
                    )
                }
            }
        }
    }
}