package com.shtcfoundation.ui.models

data class User(
    val memberId: String? = null,
    val loginEmail: String,
    val firstName: String,
    val lastName: String,
    val phone: String,
    val email: String,
    val accessLevel: AccessLevel,
    val position: String,
    val startDate: String,
    val status: Status,
    val countryOfResidence: String,
    val dob: String,
    val firstimeRegistrationCode: String,
) {
    val fullName: String = "$firstName $lastName"
}

enum class AccessLevel {
    ADMIN,
    EC,
    MEMBER;

    companion object {
        fun getAccessLevel(value: String): AccessLevel {
            return when (value) {
                "ADMIN" -> ADMIN
                "EC" -> EC
                "MEMBER" -> MEMBER
                else -> MEMBER

            }
        }
    }
}

enum class Status {
    ACTIVE,
    REGISTRATION_PENDING,
    VERIFICATION_PENDING,
    INACTIVE;

    companion object {
        fun getStatus(value: String): Status {
            return when (value) {
                "ACTIVE" -> ACTIVE
                "INACTIVE" -> INACTIVE
                "REGISTRATION_PENDING" -> REGISTRATION_PENDING
                "VERIFICATION_PENDING" -> VERIFICATION_PENDING
                else -> ACTIVE
            }
        }
    }
}