class HomeScreen : Screen {
    @OptIn(ExperimentalVoyagerApi::class, KoinExperimentalAPI::class)
    @Composable
    override fun Content() {
        val vieModel: MainViewModel = koinViewModel<MainViewModel>()
        val sharedViewModel = navigatorViewModel { vieModel }
        HomeScreenContent(viewModel = sharedViewModel)
    }
}

@OptIn(ExperimentalMaterial3Api::class, KoinExperimentalAPI::class)
@Composable
fun HomeScreenContent(
    viewModel: MainViewModel = koinViewModel<MainViewModel>(),
) {
    val state = viewModel.state.collectAsState()
    val navigator = LocalNavigator.currentOrThrow

    viewModel.getAccounts()
    viewModel.getUserDetails()

    ProgressLayout(isLoading = state.value.isLoading)

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Text(
                        text = "Home",
                        color = Color.White
                    )
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = Color(0xFF1A9771)
                )
            )
        }
    ) { paddingValues ->
        CircleBackground(2f, paddingValues)
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(top = paddingValues.calculateTopPadding()),
            contentPadding = PaddingValues(vertical = 16.dp),
            userScrollEnabled = true,
        ) {
            item {
                Text(
                    modifier = Modifier
                        .fillMaxWidth(),
                    text = "Hello ${state.value.user?.firstName ?: "User"}",
                    style = MaterialTheme.typography.headlineMedium,
                    textAlign = TextAlign.Center
                )
                Spacer(modifier = Modifier.height(32.dp))
            }

            if (state.value.user?.status == Status.ACTIVE && state.value.user?.accessLevel != AccessLevel.MEMBER) {
                if (state.value.accounts.isNotEmpty()) {
                    items(state.value.accounts) {
                        AccountItem(
                            accountType = it.accountType,
                            currentBalance = it.currentBalance,
                            collections = it.collections,
                            expenses = it.expenses,
                            pendingBalance = it.pendingBalance
                        )
                    }
                } else {
                    item {
                        Text(
                            modifier = Modifier.padding(horizontal = 16.dp).fillParentMaxSize(),
                            text = "No accounts found",
                            textAlign = TextAlign.Center,
                        )
                    }
                }

                item {
                    Spacer(modifier = Modifier.height(16.dp))
                    Text(
                        modifier = Modifier.padding(horizontal = 16.dp),
                        text = "Forms",
                        style = MaterialTheme.typography.titleLarge
                    )
                }

                item {
                    ActionCell(
                        modifier = Modifier
                            .padding(horizontal = 16.dp, vertical = 8.dp)
                            .shadow(elevation = 4.dp, shape = MaterialTheme.shapes.medium),
                        title = "Donations",
                        onClick = {
                            navigator.parent?.push(DonationsScreen())
                        }
                    )
                }

                item {
                    ActionCell(
                        modifier = Modifier
                            .padding(horizontal = 16.dp, vertical = 8.dp)
                            .shadow(elevation = 4.dp, shape = MaterialTheme.shapes.medium),
                        title = "Donors",
                        onClick = {
                            navigator.parent?.push(DonorsScreen())
                        }
                    )
                }

                item {
                    ActionCell(
                        modifier = Modifier
                            .padding(horizontal = 16.dp, vertical = 8.dp)
                            .shadow(elevation = 4.dp, shape = MaterialTheme.shapes.medium),
                        title = "Expenses",
                        onClick = {
                            navigator.parent?.push(ExpensesScreen())
                        }
                    )
                }

                item {
                    ActionCell(
                        modifier = Modifier
                            .padding(horizontal = 16.dp, vertical = 8.dp)
                            .shadow(elevation = 4.dp, shape = MaterialTheme.shapes.medium),
                        title = "EC Members",
                        onClick = {
                            navigator.parent?.push(ECMemberScreen())
                        }
                    )
                }

                item {
                    ActionCell(
                        modifier = Modifier
                            .padding(horizontal = 16.dp, vertical = 8.dp)
                            .shadow(elevation = 4.dp, shape = MaterialTheme.shapes.medium),
                        title = "Projects",
                        onClick = {
                            navigator.parent?.push(ProjectsScreen())
                        }
                    )
                }
            } else if (state.value.user?.status == Status.VERIFICATION_PENDING) {
                item {
                    Column(
                        Modifier.padding(horizontal = 16.dp).fillParentMaxSize(),
                        verticalArrangement = Arrangement.Center,
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Text(
                            modifier = Modifier.padding(bottom = 16.dp),
                            text = "Your account is not verified, please complete your profile to verify and activate it.",
                            textAlign = TextAlign.Center,
                            color = Color.White,
                            style = MaterialTheme.typography.bodyLarge,
                        )
                        TextButton(
                            modifier = Modifier,
                            onClick = {
                                navigator.parent?.push(CompleteProfileScreen())
                            }
                        ) {
                            Text(
                                text = "Complete profile",
                                textAlign = TextAlign.Center,
                                textDecoration = TextDecoration.Underline,
                                color = Color.White,
                                style = MaterialTheme.typography.bodyLarge
                            )
                        }
                    }
                }
            } else {
                item {
                    Column(
                        Modifier.padding(horizontal = 16.dp).fillParentMaxSize(),
                        verticalArrangement = Arrangement.Center,
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Text(
                            text = "Your account is inactive, contact SHTC Foundation for support.",
                            textAlign = TextAlign.Center,
                            color = Color.White,
                            style = MaterialTheme.typography.bodyLarge,
                        )
                    }
                }
            }
        }

    }
}


@Composable
fun AccountItem(
    modifier: Modifier = Modifier,
    accountType: String,
    currentBalance: String,
    collections: String,
    expenses: String,
    pendingBalance: String,
) {

    var expanded by remember { mutableStateOf(false) }

    val rotationState by animateFloatAsState(
        targetValue = if (expanded) 180f else 0f
    )

    val now = Clock.System.now()
    val tz = TimeZone.currentSystemDefault()
    val currentMonth = now.toLocalDateTime(tz).month.name

    Card(
        modifier = modifier
            .fillMaxWidth()
            .animateContentSize(
                animationSpec = tween(
                    durationMillis = 300,
                    easing = LinearOutSlowInEasing
                )
            )
            .padding(horizontal = 16.dp, vertical = 8.dp),
        onClick = {
            expanded = !expanded
        },
        elevation = CardDefaults.cardElevation(
            defaultElevation = 8.dp
        )
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .background(MaterialTheme.colorScheme.surface)
                .padding(horizontal = 16.dp, vertical = 8.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth()
            ) {
                Text(
                    modifier = Modifier.weight(1f),
                    text = accountType,
                    style = MaterialTheme.typography.titleMedium
                )
                IconButton(
                    modifier = Modifier.size(24.dp)
                        .rotate(rotationState),
                    onClick = {
                        expanded = !expanded
                    }
                ) {
                    Icon(
                        imageVector = Icons.Default.KeyboardArrowDown,
                        contentDescription = "Drop-Down Arrow"
                    )
                }
            }
            Spacer(modifier = Modifier.height(8.dp))
            Row(
                modifier = Modifier.fillMaxWidth()
            ) {
                Text(
                    modifier = Modifier.weight(1f),
                    text = "Current Balance:",
                    style = MaterialTheme.typography.bodyLarge
                )
                Text(
                    text = currentBalance,
                    style = MaterialTheme.typography.bodyLarge
                )
            }

            if (expanded) {
                Spacer(modifier = Modifier.height(8.dp))
                Row(
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        modifier = Modifier.weight(1f),
                        text = "Pending balance:",
                        style = MaterialTheme.typography.bodyLarge
                    )
                    Text(
                        text = pendingBalance,
                        style = MaterialTheme.typography.bodyLarge
                    )
                }
                Spacer(modifier = Modifier.height(8.dp))
                Row(
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        modifier = Modifier.weight(1f),
                        text = "Collections - $currentMonth:",
                        style = MaterialTheme.typography.bodyLarge
                    )
                    Text(
                        text = collections,
                        style = MaterialTheme.typography.bodyLarge
                    )
                }
                Spacer(modifier = Modifier.height(8.dp))
                Row(
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        modifier = Modifier.weight(1f),
                        text = "Expenses: - $currentMonth",
                        style = MaterialTheme.typography.bodyLarge
                    )
                    Text(
                        text = expenses,
                        style = MaterialTheme.typography.bodyLarge
                    )
                }
            }
        }
    }
}