import com.shtcfoundation.ui.models.Status
import com.shtcfoundation.ui.models.User
import kotlinx.coroutines.launch

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AddECMemberBottomSheet(
    modifier: Modifier = Modifier,
    bottomSheetState: SheetState,
    user: User? = null,
    onCancelClicked: () -> Unit,
    onSaveClicked: (user: User) -> Unit,
) {

    val scope = rememberCoroutineScope()

    var firstName by remember { mutableStateOf(user?.firstName ?: "") }
    var lastName by remember { mutableStateOf(user?.lastName ?: "") }
    var loginEmail by remember { mutableStateOf(user?.loginEmail ?: "") }
    var joiningDate by remember { mutableStateOf(user?.startDate ?: "") }
    var position by remember { mutableStateOf(user?.position ?: "") }
    var accessLevel by remember { mutableStateOf(user?.accessLevel?.name ?: "") }

    var isAccessLevelDialogVisible by remember { mutableStateOf(false) }

    val isEditMode = user != null

    // Bottom Sheet
    ModalBottomSheet(
        shape = RoundedCornerShape(topStart = 16.dp, topEnd = 16.dp),
        content = {
            Box(modifier = Modifier.padding(16.dp)) {
                Surface(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(topStart = 16.dp, topEnd = 16.dp)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth().verticalScroll(rememberScrollState())

                    ) {

                        Text(
                            text = if (isEditMode) "Edit User" else "Add User",
                            style = MaterialTheme.typography.titleLarge,
                            fontWeight = FontWeight(700),
                            color = Color.Black,
                            fontSize = 22.sp,
                            fontFamily = FontFamily.Default,
                            modifier = Modifier.align(Alignment.CenterHorizontally)
                        )

                        Spacer(modifier = Modifier.height(16.dp))

                        OutlinedTextField(
                            value = firstName,
                            onValueChange = { firstName = it },
                            label = { Text("First name") },
                            modifier = Modifier
                                .fillMaxWidth(),
                            maxLines = 1,
                            keyboardOptions = KeyboardOptions(
                                keyboardType = KeyboardType.Text,
                                imeAction = ImeAction.Done
                            )
                        )

                        Spacer(modifier = Modifier.height(8.dp))

                        OutlinedTextField(
                            value = lastName,
                            onValueChange = { lastName = it },
                            label = { Text("Last name") },
                            modifier = Modifier
                                .fillMaxWidth(),
                            maxLines = 1,
                            keyboardOptions = KeyboardOptions(
                                keyboardType = KeyboardType.Text,
                                imeAction = ImeAction.Done
                            )
                        )

                        Spacer(modifier = Modifier.height(8.dp))

                        OutlinedTextField(
                            value = loginEmail,
                            onValueChange = { loginEmail = it },
                            label = { Text("Login email") },
                            modifier = Modifier
                                .fillMaxWidth(),
                            maxLines = 1,
                            keyboardOptions = KeyboardOptions(
                                keyboardType = KeyboardType.Email,
                                imeAction = ImeAction.Done
                            )
                        )

                        Spacer(modifier = Modifier.height(8.dp))

                        OutlinedTextField(
                            value = joiningDate,
                            onValueChange = { joiningDate = it },
                            label = { Text("Joining date (dd-mm-yyyy)") },
                            modifier = Modifier
                                .fillMaxWidth(),
                            maxLines = 1,
                            keyboardOptions = KeyboardOptions(
                                keyboardType = KeyboardType.Text,
                                imeAction = ImeAction.Done
                            )
                        )

                        Spacer(modifier = Modifier.height(8.dp))

                        OutlinedTextField(
                            value = position,
                            onValueChange = { position = it },
                            label = { Text("Position") },
                            modifier = Modifier
                                .fillMaxWidth(),
                            maxLines = 1,
                            keyboardOptions = KeyboardOptions(
                                keyboardType = KeyboardType.Text,
                                imeAction = ImeAction.Done
                            )
                        )

                        Spacer(modifier = Modifier.height(8.dp))

                        OutlinedTextField(
                            value = accessLevel,
                            onValueChange = { accessLevel = it },
                            label = { Text("Access level") },
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(MaterialTheme.colorScheme.background)
                                .pointerInput(Unit) {
                                    detectTapGestures(onTap = {
                                        isAccessLevelDialogVisible = true
                                    })
                                },
                            readOnly = true,
                            enabled = false,
                            maxLines = 1,
                            colors = OutlinedTextFieldDefaults.colors(
                                disabledBorderColor = MaterialTheme.colorScheme.outline,
                                disabledContainerColor = MaterialTheme.colorScheme.background,
                                disabledTextColor = MaterialTheme.colorScheme.onBackground,
                                disabledLabelColor = MaterialTheme.colorScheme.onBackground,
                                disabledLeadingIconColor = MaterialTheme.colorScheme.onBackground,
                                disabledTrailingIconColor = MaterialTheme.colorScheme.onBackground,
                            ),
                            trailingIcon = {
                                IconButton(
                                    onClick = { isAccessLevelDialogVisible = true },
                                    modifier = Modifier.padding(start = 8.dp)
                                ) {
                                    Icon(Icons.Default.Add, contentDescription = "ADD")
                                }
                            },
                        )

                        if (isAccessLevelDialogVisible) {
                            AlertDialogListItems(
                                showDialog = true,
                                onDismissRequest = { isAccessLevelDialogVisible = false },
                                title = "Select a access level",
                                items = AccessLevel.entries.map { it.name },
                                onItemSelected = { index, item ->
                                    accessLevel = item
                                    isAccessLevelDialogVisible = false
                                },
                            )
                        }

                        Spacer(modifier = Modifier.height(24.dp))

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.End
                        ) {
                            OutlinedButton(
                                onClick = {
                                    if (
                                        firstName.isNotEmpty() && lastName.isNotEmpty() && loginEmail.isNotEmpty() && joiningDate.isNotEmpty() &&
                                        position.isNotEmpty() && accessLevel.isNotEmpty()
                                    ) {
                                        scope.launch { bottomSheetState.hide() }
                                            .invokeOnCompletion {
                                                onSaveClicked(
                                                    User(
                                                        loginEmail = loginEmail,
                                                        firstName = firstName,
                                                        lastName = lastName,
                                                        phone = "",
                                                        email = "",
                                                        accessLevel = AccessLevel.getAccessLevel(
                                                            accessLevel
                                                        ),
                                                        position = position,
                                                        status = user?.status ?: Status.REGISTRATION_PENDING,
                                                        startDate = joiningDate,
                                                        countryOfResidence = "",
                                                        dob = "",
                                                        firstimeRegistrationCode = "HUMANITY24"
                                                    )
                                                )
                                            }
                                    }
                                },
                                shape = RoundedCornerShape(50),
                                colors = ButtonDefaults.outlinedButtonColors(
                                    contentColor = Color(
                                        0xFF6750A4
                                    )
                                ),
                                modifier = Modifier.padding(8.dp)
                            ) {
                                Text(
                                    text = "Save",
                                    style = TextStyle(
                                        fontSize = 14.sp,
                                        lineHeight = 20.sp,
                                        fontFamily = FontFamily.Default,
                                        fontWeight = FontWeight(500),
                                        color = Color(0xFF6750A4),
                                        textAlign = TextAlign.Center,
                                        letterSpacing = 0.1.sp
                                    )
                                )
                            }

                            OutlinedButton(
                                onClick = {
                                    scope.launch { bottomSheetState.hide() }.invokeOnCompletion {
                                        onCancelClicked()
                                    }
                                },
                                shape = RoundedCornerShape(50),
                                colors = ButtonDefaults.outlinedButtonColors(
                                    contentColor = Color(
                                        0xFF6750A4
                                    )
                                ),
                                modifier = Modifier.padding(8.dp)
                            ) {
                                Text(
                                    text = "Cancel", style = TextStyle(
                                        fontSize = 14.sp,
                                        lineHeight = 20.sp,
                                        fontFamily = FontFamily.Default,
                                        fontWeight = FontWeight(500),
                                        color = Color(0xFF6750A4),
                                        textAlign = TextAlign.Center,
                                        letterSpacing = 0.1.sp
                                    )
                                )
                            }
                        }
                    }
                }
            }
        },
        sheetState = bottomSheetState,
        onDismissRequest = {
            onCancelClicked()
        }
    )
}