class DonorsScreen : Screen {
    @Composable
    override fun Content() {
        DonorsScreenContent()
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun DonorsScreenContent(
    firestore: FirestoreImpl = FirestoreImpl(Firebase.firestore, Firebase.auth)
) {
    val navigator = LocalNavigator.currentOrThrow
    val scope = rememberCoroutineScope()

    var donors: List<Donor> by remember { mutableStateOf(emptyList()) }
    var members: List<Member> by remember { mutableStateOf(emptyList()) }
    var ecMembers: List<ECMember> by remember { mutableStateOf(emptyList()) }

    var currentFullDonor: FullDonor? by remember { mutableStateOf(null) }

    scope.launch {
        donors = firestore.getDonors()
        members = firestore.getMembers()
        ecMembers = firestore.getECMembers()
    }

    var showBottomSheet by remember { mutableStateOf(false) }

    val bottomSheetState = rememberModalBottomSheetState(
        skipPartiallyExpanded = true,
    )

    if (showBottomSheet) {
        DonorBottomSheet(
            onCancelClicked = {
                showBottomSheet = false
                currentFullDonor = null
            },
            onSaveClicked = { donor, member ->
                showBottomSheet = false
                currentFullDonor = null
                val memberId = member.id.ifEmpty { members.size.toString() }
                scope.launch {
                    firestore.addMember(member.copy(id = memberId))
                    firestore.addDonor(
                        donor.copy(
                            id = donor.id.ifEmpty { donors.size.toString() },
                            memberID = memberId
                        )
                    )
                }.invokeOnCompletion {
                    scope.launch {
                        donors = firestore.getDonors()
                        members = firestore.getMembers()
                        ecMembers = firestore.getECMembers()
                    }
                }
            },
            bottomSheetState = bottomSheetState,
            ecMembers = ecMembers.map {
                val member = members.find { member -> member.id == it.memberId }!!
                member.firstName + " " + member.lastName
            },
            donor = currentFullDonor?.donor,
            member = currentFullDonor?.member
        )
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Text(
                        text = "Donors",
                        color = Color.White
                    )
                },
                navigationIcon = {
                    IconButton(
                        onClick = {
                            navigator.pop()
                        }
                    ) {
                        Icon(
                            imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                            contentDescription = "Back",
                            tint = Color.White
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = Color(0xFF1A9771)
                )
            )
        },
        bottomBar = {
            Row(
                modifier = Modifier.fillMaxWidth().padding(16.dp),
            ) {
                Spacer(modifier = Modifier.weight(1f))
                FloatingActionButton(
                    onClick = {
                        showBottomSheet = true
                    },
                    containerColor = Color(0xFF00DBA6)
                ) {
                    Icon(
                        imageVector = Icons.Default.Add,
                        tint = Color.White,
                        contentDescription = "Back"
                    )
                }
            }
        },
        containerColor = Color(0xFFFAF9F6)
    ) { paddingValues ->
        CircleBackground(2f, paddingValues)
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues),
            contentPadding = PaddingValues(vertical = 16.dp),
            userScrollEnabled = true,
        ) {
            if (donors.isNotEmpty() && members.isNotEmpty() && ecMembers.isNotEmpty()) {
                items(donors) { donor ->
                    DonorItem(
                        fullDonor = getFullDonor(
                            donor = donor,
                            member = members.find { it.id == donor.memberID }!!
                        ),
                        onEditClicked = { fullDonor ->
                            currentFullDonor = fullDonor
                            showBottomSheet = true
                        }
                    )
                }
            } else {
                item {
                    Text(
                        modifier = Modifier.padding(horizontal = 16.dp).fillParentMaxSize(),
                        text = "No donors found",
                        textAlign = TextAlign.Center,
                    )
                }
            }
        }
    }
}

@Composable
fun DonorItem(
    modifier: Modifier = Modifier,
    fullDonor: FullDonor,
    onEditClicked: (fullDonor: FullDonor) -> Unit = {}
) {
    var expanded by remember { mutableStateOf(false) }

    Card(
        modifier = modifier
            .fillMaxWidth()
            .animateContentSize(
                animationSpec = tween(
                    durationMillis = 300,
                    easing = LinearOutSlowInEasing
                )
            )
            .padding(horizontal = 16.dp, vertical = 4.dp),
        onClick = {
            expanded = !expanded
        },
        elevation = CardDefaults.cardElevation(
            defaultElevation = 8.dp
        )
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .background(MaterialTheme.colorScheme.surface)
                .padding(horizontal = 16.dp, vertical = 8.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth()
            ) {
                Text(
                    modifier = Modifier.weight(1f),
                    text = fullDonor.fullName,
                    style = MaterialTheme.typography.titleMedium
                )
                Text(
                    text = fullDonor.donor.frequency,
                    style = MaterialTheme.typography.bodyLarge
                )
            }

            if (expanded) {
                Spacer(modifier = Modifier.height(8.dp))
                Row(
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        modifier = Modifier.weight(1f),
                        text = "Amount: ",
                        style = MaterialTheme.typography.bodyLarge
                    )
                    Text(
                        text = fullDonor.donor.currency + " " + fullDonor.donor.amount,
                        style = MaterialTheme.typography.bodyLarge
                    )
                }
                Spacer(modifier = Modifier.height(8.dp))
                Row(
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        modifier = Modifier.weight(1f),
                        text = "Email: ",
                        style = MaterialTheme.typography.bodyLarge
                    )
                    Text(
                        text = fullDonor.member.email,
                        style = MaterialTheme.typography.bodyLarge
                    )
                }
                Spacer(modifier = Modifier.height(8.dp))
                Row(
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        modifier = Modifier.weight(1f),
                        text = "Phone: ",
                        style = MaterialTheme.typography.bodyLarge
                    )
                    Text(
                        text = fullDonor.member.phone,
                        style = MaterialTheme.typography.bodyLarge
                    )
                }
                Spacer(modifier = Modifier.height(8.dp))
                Row(
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        modifier = Modifier.weight(1f),
                        text = "Starting Date: ",
                        style = MaterialTheme.typography.bodyLarge
                    )
                    Text(
                        text = fullDonor.member.joiningDate,
                        style = MaterialTheme.typography.bodyLarge
                    )
                }
                Spacer(modifier = Modifier.height(8.dp))
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.End
                ) {
                    OutlinedButton(
                        onClick = {
                            onEditClicked(fullDonor)
                        },
                        shape = RoundedCornerShape(50),
                        colors = ButtonDefaults.outlinedButtonColors(
                            contentColor = Color(
                                0xFF6750A4
                            )
                        ),
                        modifier = Modifier.padding(4.dp)
                    ) {
                        Text(
                            text = "Edit", style = TextStyle(
                                fontSize = 14.sp,
                                lineHeight = 20.sp,
                                fontFamily = FontFamily.Default,
                                fontWeight = FontWeight(500),
                                color = Color(0xFF6750A4),
                                textAlign = TextAlign.Center,
                                letterSpacing = 0.1.sp
                            )
                        )
                    }
                }
            }
        }
    }
}

fun getFullDonor(donor: Donor, member: Member): FullDonor {
    return FullDonor(
        fullName = member.firstName + " " + member.lastName,
        donor = donor,
        member = member
    )
}

data class FullDonor(
    val fullName: String,
    val donor: Donor,
    val member: Member
)
