package com.shtcfoundation.di

import com.shtcfoundation.data.auth.AuthService
import com.shtcfoundation.data.auth.AuthServiceIml
import com.shtcfoundation.data.firestore.FirestoreImpl
import com.shtcfoundation.ui.MainViewModel
import dev.gitlive.firebase.Firebase
import dev.gitlive.firebase.auth.FirebaseAuth
import dev.gitlive.firebase.auth.auth
import dev.gitlive.firebase.firestore.FirebaseFirestore
import dev.gitlive.firebase.firestore.firestore
import org.koin.compose.viewmodel.dsl.viewModelOf
import org.koin.dsl.module

val appModule = module {
    viewModelOf(::MainViewModel)

    single<AuthService> { AuthServiceIml(get()) }
    single<FirebaseAuth> { Firebase.auth }
    single<FirebaseFirestore> { Firebase.firestore }
    single { FirestoreImpl(get(), get()) }
}