package com.shtcfoundation.ui.splash

import androidx.compose.foundation.Image
import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.Spacer
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.height
import androidx.compose.foundation.layout.size
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.TileMode
import androidx.compose.ui.unit.dp
import cafe.adriel.voyager.core.screen.Screen
import org.jetbrains.compose.resources.painterResource
import shtcfoundation.composeapp.generated.resources.Res
import shtcfoundation.composeapp.generated.resources.shtcLogo

class SplashScreen : Screen {
    @Composable
    override fun Content() {
        SplashContent()
    }
}

@Composable
fun SplashContent() {
    val linearGradient = Brush.linearGradient(
        colors = listOf(
            Color(0XFFF5EAFF),
            Color(0XFFF0EEF6)
        ),
        start = Offset(0f, 0f),
        end = Offset(100f, 100f),
        tileMode = TileMode.Clamp
    )
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(linearGradient),
        contentAlignment = Alignment.Center
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            Image(
                modifier = Modifier.size(150.dp),
                painter = painterResource(Res.drawable.shtcLogo),
                contentDescription = "SHTC Foundation",
            )
            Spacer(modifier = Modifier.height(16.dp))
            Text(
                text = "SHTC Foundation",
                style = MaterialTheme.typography.headlineMedium
            )
        }

    }
}