class LoginScreen : Screen {
    @OptIn(KoinExperimentalAPI::class, ExperimentalVoyagerApi::class)
    @Composable
    override fun Content() {
        val vieModel: MainViewModel = koinViewModel<MainViewModel>()
        val sharedViewModel = navigatorViewModel { vieModel }
        LoginContent(viewModel = sharedViewModel)
    }
}

@OptIn(KoinExperimentalAPI::class)
@Composable
fun LoginContent(
    viewModel: MainViewModel = koinViewModel(),
) {
    val navigator = LocalNavigator.currentOrThrow

    var email by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }
    var loginError by remember { mutableStateOf("") }
    var showPassword by remember { mutableStateOf(false) }

//    viewModel.login("monju@shtc.org", "Humanity24")

    LaunchedEffect(viewModel.event) {
        viewModel.event.collect { event ->
            when (event) {
                is MainEvent.EmailVerified -> { /*no op*/
                }

                is MainEvent.LoginError -> {
                    loginError = event.error
                }

                is MainEvent.LoginSuccess -> {
                    navigator.push(MainScreen())
                }

                is MainEvent.RegistrationError -> { /*no op*/
                }

                is MainEvent.RegistrationSuccess -> { /*no op*/
                }

                else -> { /*no op*/
                }
            }
        }
    }

    Surface(
        modifier = Modifier.fillMaxSize(),
        contentColor = Color.White
    ) {
        OnboardingCircleBackground()
        Column(
            modifier = Modifier.fillMaxSize().padding(horizontal = 16.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
                modifier = Modifier.padding(top = 32.dp),
                text = "SHTC Foundation",
                style = MaterialTheme.typography.headlineMedium
            )
            Text(
                modifier = Modifier.padding(top = 32.dp),
                text = "Welcome",
                style = MaterialTheme.typography.headlineMedium
            )
            if (loginError.isNotEmpty()) {
                Text(
                    text = loginError,
                    color = MaterialTheme.colorScheme.error,
                    style = MaterialTheme.typography.bodyLarge
                )
            } else {
                Text(
                    modifier = Modifier.padding(top = 16.dp),
                    text = "Please enter your email and password",
                    style = MaterialTheme.typography.bodyLarge
                )
            }

            OutlinedTextField(
                modifier = Modifier.padding(top = 16.dp)
                    .fillMaxWidth(),
                value = email,
                onValueChange = {
                    email = it
                },
                label = {
                    Text("Enter your email")
                },
                keyboardOptions = KeyboardOptions(
                    keyboardType = KeyboardType.Email
                ),
                colors = OutlinedTextFieldDefaults.colors(
                    focusedBorderColor = Color(0xFF00DBA6),
                    unfocusedBorderColor = Color(0xFF00DBA6),
                    focusedContainerColor = Color.White,
                    unfocusedContainerColor = Color.White,
                    focusedTextColor = Color.Black,
                    unfocusedTextColor = Color.Black,
                    unfocusedLabelColor = Color.LightGray,
                    focusedLabelColor = Color.LightGray,
                    cursorColor = Color(0xFF00DBA6),
                ),
                shape = MaterialTheme.shapes.medium
            )

            OutlinedTextField(
                modifier = Modifier.padding(top = 16.dp)
                    .fillMaxWidth(),
                value = password,
                onValueChange = {
                    password = it
                },
                label = {
                    Text("Enter your password")
                },
                keyboardOptions = KeyboardOptions(
                    keyboardType = KeyboardType.Password
                ),
                colors = OutlinedTextFieldDefaults.colors(
                    focusedBorderColor = Color(0xFF00DBA6),
                    unfocusedBorderColor = Color(0xFF00DBA6),
                    focusedContainerColor = Color.White,
                    unfocusedContainerColor = Color.White,
                    focusedTextColor = Color.Black,
                    unfocusedTextColor = Color.Black,
                    unfocusedLabelColor = Color.LightGray,
                    focusedLabelColor = Color.LightGray,
                    cursorColor = Color(0xFF00DBA6),
                ),
                visualTransformation = if (showPassword) VisualTransformation.None
                else PasswordVisualTransformation(),
                trailingIcon = {
                    IconButton(onClick = { showPassword = !showPassword }) {
                        if (!showPassword) {
                            Icon(
                                painter = painterResource(Res.drawable.ic_visible),
                                contentDescription = "Show password"
                            )
                        } else {
                            Icon(
                                painter = painterResource(Res.drawable.ic_invisible),
                                contentDescription = "Hide password"
                            )
                        }
                    }
                },
                shape = MaterialTheme.shapes.medium
            )
            Spacer(modifier = Modifier.height(16.dp))
            Button(
                modifier = Modifier.fillMaxWidth(),
                colors = ButtonDefaults.buttonColors(
                    containerColor = Color(0xFF00DBA6),
                ),
                onClick = {
                    loginError = ""
                    viewModel.login(email, password)
                }
            ) {
                Text("Login")
            }
            Text(
                modifier = Modifier.padding(top = 16.dp),
                text = "Don't have an account?",
                style = MaterialTheme.typography.headlineSmall
            )
            TextButton(
                modifier = Modifier.fillMaxWidth(),
                colors = ButtonDefaults.textButtonColors(
                    contentColor = Color.White,
                ),
                onClick = {
                    navigator.push(RegistrationScreen())
                }
            ) {
                Text("Click to register")
            }

            Spacer(modifier = Modifier.weight(1f))

            Row(
                horizontalArrangement = Arrangement.Center
            ) {
                Image(
                    painter = painterResource(Res.drawable.shtcLogo),
                    contentDescription = "SHTC Foundation",
                    modifier = Modifier
                        .size(150.dp)
                        .padding(bottom = 16.dp)
                )
            }
        }
    }
}