package com.shtcfoundation.ui.models

enum class Country {
    UK, USA, JAPAN, BANGLADESH, MALAYSIA;

    companion object {
        fun fromString(value: String): Country {
            return when (value) {
                "UK" -> UK
                "USA" -> USA
                "JAPAN" -> JAPAN
                "BANGLADESH" -> BANGLADESH
                "MALAYSIA" -> MALAYSIA
                else -> UK
            }
        }
    }
}