import com.shtcfoundation.ui.donations.SelectableTextField
import com.shtcfoundation.ui.models.Currency
import com.shtcfoundation.ui.models.Frequency
import com.shtcfoundation.ui.models.ProjectCategories
import com.shtcfoundation.ui.models.ProjectStatus
import kotlinx.coroutines.launch

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AddProjectBottomSheet(
    bottomSheetState: SheetState,
    project: Project? = null,
    onCancelClicked: () -> Unit,
    onSaveClicked: (project: Project) -> Unit,
) {

    val scope = rememberCoroutineScope()

    var name by remember { mutableStateOf(project?.name ?: "") }
    var category by remember { mutableStateOf(project?.category ?: "") }
    var budget by remember { mutableStateOf(project?.budget?.toString() ?: "") }
    var currency by remember { mutableStateOf(project?.currency ?: "") }
    var description by remember { mutableStateOf(project?.description ?: "") }
    var startDate by remember { mutableStateOf(project?.startDate ?: "") }
    var endDate by remember { mutableStateOf(project?.endDate ?: "") }
    var status by remember { mutableStateOf(project?.status ?: "") }
    var frequency by remember { mutableStateOf(project?.frequency ?: "") }

    var isError by remember { mutableStateOf(false) }

    val isEditMode = project != null

    // Bottom Sheet
    ModalBottomSheet(
        shape = RoundedCornerShape(topStart = 16.dp, topEnd = 16.dp),
        content = {
            Box(modifier = Modifier.padding(16.dp)) {
                Surface(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(topStart = 16.dp, topEnd = 16.dp)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth().verticalScroll(rememberScrollState())

                    ) {

                        Text(
                            text = if (isEditMode) "Edit Project" else "Add Project",
                            style = MaterialTheme.typography.titleLarge,
                            fontWeight = FontWeight(700),
                            color = Color.Black,
                            fontSize = 22.sp,
                            fontFamily = FontFamily.Default,
                            modifier = Modifier.align(Alignment.CenterHorizontally)
                        )

                        OutlinedTextField(
                            value = name,
                            onValueChange = { name = it },
                            label = { Text("Project name") },
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                            maxLines = 1,
                            keyboardOptions = KeyboardOptions(
                                keyboardType = KeyboardType.Text,
                                imeAction = ImeAction.Done
                            )
                        )

                        SelectableTextField(
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                            value = category,
                            label = "Project category",
                            dialogTitle = "Select a project category",
                            items = ProjectCategories.entries.map { it.name },
                            onItemSelected = { index, item ->
                                category = item
                            }
                        )

                        Row(
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                        ) {
                            OutlinedTextField(
                                value = budget,
                                onValueChange = { budget = it },
                                label = { Text("Budget") },
                                modifier = Modifier.weight(1f),
                                maxLines = 1,
                                keyboardOptions = KeyboardOptions(
                                    keyboardType = KeyboardType.Number,
                                    imeAction = ImeAction.Done
                                )
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            SelectableTextField(
                                modifier = Modifier.weight(1f),
                                value = currency,
                                label = "Currency",
                                dialogTitle = "Select currency",
                                items = Currency.entries.map { it.name },
                                onItemSelected = { index, item ->
                                    currency = item
                                }
                            )
                        }
                        OutlinedTextField(
                            value = description,
                            onValueChange = { description = it },
                            label = { Text("Project description") },
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                            maxLines = 1,
                            keyboardOptions = KeyboardOptions(
                                keyboardType = KeyboardType.Text,
                                imeAction = ImeAction.Done
                            )
                        )

                        OutlinedTextField(
                            value = startDate,
                            onValueChange = { startDate = it },
                            label = { Text("Start date (dd-mm-yyyy)") },
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                            maxLines = 1,
                            keyboardOptions = KeyboardOptions(
                                keyboardType = KeyboardType.Text,
                                imeAction = ImeAction.Done
                            )
                        )

                        OutlinedTextField(
                            value = endDate,
                            onValueChange = { endDate = it },
                            label = { Text("End date (dd-mm-yyyy)") },
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                            maxLines = 1,
                            keyboardOptions = KeyboardOptions(
                                keyboardType = KeyboardType.Text,
                                imeAction = ImeAction.Done
                            )
                        )

                        SelectableTextField(
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                            value = frequency,
                            label = "Frequency",
                            dialogTitle = "Select a frequency",
                            items = Frequency.getList(),
                            onItemSelected = { index, item ->
                                frequency = item
                            }
                        )

                        SelectableTextField(
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                            value = status,
                            label = "Status",
                            dialogTitle = "Select a status",
                            items = ProjectStatus.entries.map { it.name },
                            onItemSelected = { index, item ->
                                status = item
                            }
                        )

                        Spacer(modifier = Modifier.height(24.dp))

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.End
                        ) {
                            OutlinedButton(
                                onClick = {
                                    if (
                                        name.isNotEmpty() &&
                                        category.isNotEmpty() &&
                                        budget.isNotEmpty() &&
                                        currency.isNotEmpty() &&
                                        startDate.isNotEmpty() &&
                                        frequency.isNotEmpty() &&
                                        status.isNotEmpty()
                                    ) {
                                        isError = false
                                        val budgetValue = try {
                                            budget.toLong()
                                        } catch (e: NumberFormatException) {
                                            isError = true
                                            0
                                        }
                                        if (!isError) {
                                            scope.launch { bottomSheetState.hide() }
                                                .invokeOnCompletion {
                                                    onSaveClicked(
                                                        Project(
                                                            id = project?.id ?: "",
                                                            name = name,
                                                            category = category,
                                                            budget = budgetValue,
                                                            currency = currency,
                                                            description = description,
                                                            startDate = startDate,
                                                            endDate = endDate,
                                                            frequency = frequency,
                                                            status = status,
                                                        )
                                                    )
                                                }
                                        }
                                    } else {
                                        isError = true
                                    }
                                },
                                shape = RoundedCornerShape(50),
                                colors = ButtonDefaults.outlinedButtonColors(
                                    contentColor = Color(
                                        0xFF6750A4
                                    )
                                ),
                                modifier = Modifier.padding(8.dp)
                            ) {
                                Text(
                                    text = "Save",
                                    style = TextStyle(
                                        fontSize = 14.sp,
                                        lineHeight = 20.sp,
                                        fontFamily = FontFamily.Default,
                                        fontWeight = FontWeight(500),
                                        color = Color(0xFF6750A4),
                                        textAlign = TextAlign.Center,
                                        letterSpacing = 0.1.sp
                                    )
                                )
                            }

                            OutlinedButton(
                                onClick = {
                                    scope.launch { bottomSheetState.hide() }.invokeOnCompletion {
                                        onCancelClicked()
                                    }
                                },
                                shape = RoundedCornerShape(50),
                                colors = ButtonDefaults.outlinedButtonColors(
                                    contentColor = Color(
                                        0xFF6750A4
                                    )
                                ),
                                modifier = Modifier.padding(8.dp)
                            ) {
                                Text(
                                    text = "Cancel", style = TextStyle(
                                        fontSize = 14.sp,
                                        lineHeight = 20.sp,
                                        fontFamily = FontFamily.Default,
                                        fontWeight = FontWeight(500),
                                        color = Color(0xFF6750A4),
                                        textAlign = TextAlign.Center,
                                        letterSpacing = 0.1.sp
                                    )
                                )
                            }
                        }
                    }
                }
            }
        },
        sheetState = bottomSheetState,
        onDismissRequest = {
            onCancelClicked()
        }
    )
}