package com.shtcfoundation.data.firestore

import com.shtcfoundation.data.model.Account
import com.shtcfoundation.data.model.Donation
import com.shtcfoundation.data.model.Donor
import com.shtcfoundation.data.model.ECMember
import com.shtcfoundation.data.model.Expense
import com.shtcfoundation.data.model.Member
import com.shtcfoundation.data.model.Project
import dev.gitlive.firebase.auth.FirebaseAuth
import dev.gitlive.firebase.firestore.FirebaseFirestore

class FirestoreImpl(
    private val firestore: FirebaseFirestore, // = Firebase.firestore
    private val firebaseAuth: FirebaseAuth
) {
    val userEmail = firebaseAuth.currentUser?.email

    companion object {
        const val COLLECTION_NAME_ACCOUNTS = "accounts"
        const val COLLECTION_NAME_DONATIONS = "donations"
        const val COLLECTION_NAME_DONORS = "donors"
        const val COLLECTION_NAME_EC_MEMBERS = "ec_members"
        const val COLLECTION_NAME_EXPENSES = "expenses"
        const val COLLECTION_NAME_MEMBERS = "members"
        const val COLLECTION_NAME_PROJECTS = "projects"
        const val COLLECTION_NAME_TRANSACTIONS = "transactions"
    }

    suspend fun getAccounts(): List<Account> {
        return try {
            firestore.collection(COLLECTION_NAME_ACCOUNTS).get().documents.map {
                val accountData: Account = it.data()
                Account(
                    id = it.id,
                    name = accountData.name,
                    balance = accountData.balance,
                    currency = accountData.currency,
                    country = accountData.country,
                    pending = accountData.pending
                )
            }
        } catch (e: Exception) {
            throw e
        }
    }

    suspend fun getDonations(): List<Donation> {
        return try {
            firestore.collection(COLLECTION_NAME_DONATIONS).get().documents.map {
                val donationData: Donation = it.data()
                Donation(
                    id = it.id,
                    donorId = donationData.donorId,
                    amount = donationData.amount,
                    currency = donationData.currency,
                    frequency = donationData.frequency,
                    accountId = donationData.accountId,
                    donationCountry = donationData.donationCountry,
                    paymentDate = donationData.paymentDate,
                    status = donationData.status,
                    fundraiserId = donationData.fundraiserId,
                    pledgeDate = donationData.pledgeDate,
                    projectId = donationData.projectId,
                    remarks = donationData.remarks,
                )
            }
        } catch (e: Exception) {
            throw e
        }
    }

    suspend fun getDonors(): List<Donor> {
        return try {
            firestore.collection(COLLECTION_NAME_DONORS).get().documents.map {
                val donorData: Donor = it.data()
                Donor(
                    id = it.id,
                    addedBy = donorData.addedBy,
                    amount = donorData.amount,
                    currency = donorData.currency,
                    frequency = donorData.frequency,
                    memberID = donorData.memberID,
                    startingDate = donorData.startingDate
                )
            }
        } catch (e: Exception) {
            throw e
        }
    }

    suspend fun getExpenses(): List<Expense> {
        return try {
            firestore.collection(COLLECTION_NAME_EXPENSES).get().documents.map {
                val expenseData: Expense = it.data()
                Expense(
                    id = it.id,
                    amount = expenseData.amount,
                    budget = expenseData.budget,
                    currency = expenseData.currency,
                    country = expenseData.country,
                    date = expenseData.date,
                    ecMemberId = expenseData.ecMemberId,
                    fromAccountId = expenseData.fromAccountId,
                    projectId = expenseData.projectId,
                    purpose = expenseData.purpose,
                    remarks = expenseData.remarks,
                    frequency = expenseData.frequency
                )
            }
        } catch (e: Exception) {
            throw e
        }
    }

    suspend fun getProjects(): List<Project> {
        return try {
            firestore.collection(COLLECTION_NAME_PROJECTS).get().documents.map {
                val projectData: Project = it.data()
                Project(
                    id = it.id,
                    budget = projectData.budget,
                    category = projectData.category,
                    description = projectData.description,
                    frequency = projectData.frequency,
                    name = projectData.name,
                    status = projectData.status,
                    startDate = projectData.startDate,
                    endDate = projectData.endDate,
                    currency = projectData.currency
                )
            }
        } catch (e: Exception) {
            throw e
        }
    }

    suspend fun getMembers(): List<Member> {
        return try {
            firestore.collection(COLLECTION_NAME_MEMBERS).get().documents.map {
                val memberData: Member = it.data()
                Member(
                    id = it.id,
                    countryOfResidence = memberData.countryOfResidence,
                    dob = memberData.dob,
                    email = memberData.email,
                    phone = memberData.phone,
                    firstName = memberData.firstName,
                    lastName = memberData.lastName,
                    joiningDate = memberData.joiningDate
                )
            }
        } catch (e: Exception) {
            throw e
        }
    }

    suspend fun getECMembers(): List<ECMember> {
        return try {
            firestore.collection(COLLECTION_NAME_EC_MEMBERS).get().documents.map {
                val ecMemberData: ECMember = it.data()
                ECMember(
                    id = it.id,
                    accessLevel = ecMemberData.accessLevel,
                    loginEmail = ecMemberData.loginEmail,
                    memberId = ecMemberData.memberId,
                    position = ecMemberData.position,
                    startDate = ecMemberData.startDate,
                    userId = ecMemberData.userId,
                    status = ecMemberData.status,
                    firstimeRegistrationCode = ecMemberData.firstimeRegistrationCode
                )
            }
        } catch (e: Exception) {
            throw e
        }
    }

    suspend fun addDonor(donor: Donor) {
        try {
            firestore.collection(COLLECTION_NAME_DONORS).document(donor.id).set(
                hashMapOf(
                    "addedBy" to donor.addedBy,
                    "amount" to donor.amount,
                    "currency" to donor.currency,
                    "frequency" to donor.frequency,
                    "memberID" to donor.memberID,
                    "startingDate" to donor.startingDate,
                )
            )
        } catch (e: Exception) {
            throw e
        }
    }

    suspend fun addMember(member: Member) {
        try {
            firestore.collection(COLLECTION_NAME_MEMBERS).document(member.id).set(
                hashMapOf(
                    "countryOfResidence" to member.countryOfResidence,
                    "dob" to member.dob,
                    "email" to member.email,
                    "phone" to member.phone,
                    "firstName" to member.firstName,
                    "lastName" to member.lastName,
                    "joiningDate" to member.joiningDate,
                )
            )
        } catch (e: Exception) {
            throw e
        }
    }

    suspend fun addECMember(ecMember: ECMember) {
        try {
            firestore.collection(COLLECTION_NAME_EC_MEMBERS).document(ecMember.id).set(
                hashMapOf(
                    "accessLevel" to ecMember.accessLevel,
                    "loginEmail" to ecMember.loginEmail,
                    "memberId" to ecMember.memberId,
                    "position" to ecMember.position,
                    "startDate" to ecMember.startDate,
                    "userId" to ecMember.userId,
                    "status" to ecMember.status,
                    "firstimeRegistrationCode" to ecMember.firstimeRegistrationCode
                )
            )
        } catch (e: Exception) {
            throw e
        }
    }

    suspend fun addProject(project: Project) {
        try {
            firestore.collection(COLLECTION_NAME_PROJECTS).document(project.id).set(
                hashMapOf(
                    "budget" to project.budget,
                    "category" to project.category,
                    "description" to project.description,
                    "frequency" to project.frequency,
                    "name" to project.name,
                    "status" to project.status,
                    "startDate" to project.startDate,
                    "endDate" to project.endDate,
                    "currency" to project.currency
                )
            )
        } catch (e: Exception) {
            throw e
        }
    }

    suspend fun addDonation(donation: Donation) {
        try {
            firestore.collection(COLLECTION_NAME_DONATIONS).document(donation.id).set(
                hashMapOf(
                    "accountId" to donation.accountId,
                    "amount" to donation.amount,
                    "currency" to donation.currency,
                    "donationCountry" to donation.donationCountry,
                    "donorId" to donation.donorId,
                    "frequency" to donation.frequency,
                    "fundraiserId" to donation.fundraiserId,
                    "paymentDate" to donation.paymentDate,
                    "pledgeDate" to donation.pledgeDate,
                    "projectId" to donation.projectId,
                    "remarks" to donation.remarks,
                    "status" to donation.status,
                )
            )
        } catch (e: Exception) {
            throw e
        }
    }

    suspend fun addExpense(expense: Expense) {
        try {
            firestore.collection(COLLECTION_NAME_EXPENSES).document(expense.id).set(
                hashMapOf(
                    "amount" to expense.amount,
                    "budget" to expense.budget,
                    "currency" to expense.currency,
                    "country" to expense.country,
                    "date" to expense.date,
                    "ecMemberId" to expense.ecMemberId,
                    "fromAccountId" to expense.fromAccountId,
                    "projectId" to expense.projectId,
                    "purpose" to expense.purpose,
                    "remarks" to expense.remarks,
                    "frequency" to expense.frequency,
                )
            )
        } catch (e: Exception) {
            throw e
        }
    }

    suspend fun updateAccount(account: Account) {
        try {
            firestore.collection(COLLECTION_NAME_ACCOUNTS).document(account.id).set(
                hashMapOf(
                    "name" to account.name,
                    "balance" to account.balance,
                    "currency" to account.currency,
                    "country" to account.country,
                    "pending" to account.pending,
                )
            )
        } catch (e: Exception) {
            throw e
        }
    }
}