class MainViewModel(
    private val authService: AuthService,
    private val firestore: FirestoreImpl,
) : ViewModel() {
    private val _state = MutableStateFlow(MainState())
    val state = _state.asStateFlow()

    private val _event = Channel<MainEvent?>(Channel.BUFFERED)
    val event = _event.receiveAsFlow()

    private var ecMember: ECMember? = null

//    init {
//        getAccounts()
//        getUserDetails()
//    }

    fun getAccounts() {
        viewModelScope.launch {
            showLoading()
            val accounts = firestore.getAccounts().map { acc ->
                Account(
                    id = acc.id,
                    accountType = acc.name,
                    currentBalance = acc.currency + " " + acc.balance.toString(),
                    collections = 0.toString(),
                    expenses = 0.toString(),
                    pendingBalance = acc.currency + " " + acc.pending.toString()
                )
            }
            _state.update {
                it.copy(accounts = accounts)
            }
            hideLoading()
        }
    }

    @OptIn(ExperimentalCoroutinesApi::class)
    fun getUserDetails() {
        viewModelScope.launch {
            showLoading()
            val members = async { firestore.getMembers() }
            val ecMembers = async { firestore.getECMembers() }
            awaitAll(members, ecMembers)
            val currentECMember =
                ecMembers.getCompleted().find { it.loginEmail == authService.email }
            val currentMember = members.getCompleted().find { it.id == currentECMember?.memberId }
            val user = User(
                loginEmail = currentECMember?.loginEmail ?: "",
                firstName = currentMember?.firstName ?: "",
                lastName = currentMember?.lastName ?: "",
                phone = currentMember?.phone ?: "",
                email = currentMember?.email ?: "",
                accessLevel = AccessLevel.getAccessLevel(currentECMember?.accessLevel ?: ""),
                position = currentECMember?.position ?: "",
                status = Status.getStatus(currentECMember?.status ?: ""),
                startDate = currentECMember?.startDate ?: "",
                countryOfResidence = currentMember?.countryOfResidence ?: "",
                dob = currentMember?.dob ?: "",
                firstimeRegistrationCode = currentECMember?.firstimeRegistrationCode ?: "",
                memberId = currentMember?.id
            )
            _state.update {
                it.copy(
                    user = user,
                    members = members.getCompleted(),
                )
            }
            hideLoading()
        }
    }

    @OptIn(ExperimentalCoroutinesApi::class)
    fun getECMemberList() {
        viewModelScope.launch {
            showLoading()

            val members = async { firestore.getMembers() }
            val ecMembers = async { firestore.getECMembers() }
            awaitAll(members, ecMembers)
            val users = ecMembers.getCompleted().map { ecMember ->
                val member = members.getCompleted().find { it.id == ecMember.memberId }
                User(
                    loginEmail = ecMember.loginEmail,
                    firstName = member?.firstName ?: "",
                    lastName = member?.lastName ?: "",
                    phone = member?.phone ?: "",
                    email = member?.email ?: "",
                    accessLevel = AccessLevel.getAccessLevel(ecMember.accessLevel),
                    position = ecMember.position,
                    status = Status.getStatus(ecMember.status),
                    startDate = ecMember.startDate,
                    countryOfResidence = member?.countryOfResidence ?: "",
                    dob = member?.dob ?: "",
                    firstimeRegistrationCode = ecMember.firstimeRegistrationCode,
                    memberId = member?.id
                )
            }
            _state.update {
                it.copy(
                    members = members.getCompleted(),
                    ecMembers = users
                )
            }
            hideLoading()
        }
    }

    @OptIn(ExperimentalCoroutinesApi::class)
    fun getDonations() {
        viewModelScope.launch {
            showLoading()
            val donations = async { firestore.getDonations() }
            val donors = async { firestore.getDonors() }
            val members = async { firestore.getMembers() }
            awaitAll(donations, donors, members)
            val fullDonationList = donations.getCompleted().map { donation ->
                val donor = donors.getCompleted().find { it.id == donation.donorId }!!
                val member = members.getCompleted().find { it.id == donor.memberID }!!
                FullDonation(
                    donor = donor,
                    member = member,
                    donation = donation
                )
            }
            _state.update { it.copy(donations = fullDonationList) }
            hideLoading()
        }
    }

    fun getMembers() {
        viewModelScope.launch {
            showLoading()
            val members = firestore.getMembers()
            _state.update { it.copy(members = members) }
            hideLoading()
        }
    }

    fun getProjects() {
        viewModelScope.launch {
            showLoading()
            val projects = firestore.getProjects()
            _state.update { it.copy(projects = projects) }
            hideLoading()
        }
    }

    @OptIn(ExperimentalCoroutinesApi::class)
    fun getDonors() {
        viewModelScope.launch {
            showLoading()
            val members = async { firestore.getMembers() }
            val donors = async { firestore.getDonors() }
            awaitAll(members, donors)
            val users = donors.getCompleted().map { donor ->
                val member = members.getCompleted().find { it.id == donor.memberID }
                User(
                    loginEmail = "",
                    firstName = member?.firstName ?: "",
                    lastName = member?.lastName ?: "",
                    phone = member?.phone ?: "",
                    email = member?.email ?: "",
                    accessLevel = AccessLevel.getAccessLevel(""),
                    position = "",
                    status = Status.getStatus(""),
                    startDate = donor.startingDate,
                    countryOfResidence = member?.countryOfResidence ?: "",
                    dob = member?.dob ?: "",
                    firstimeRegistrationCode = "",
                    memberId = member?.id
                )
            }
            _state.update { it.copy(donors = users) }
            hideLoading()
        }
    }

    fun addECMember(user: User) {
        viewModelScope.launch {
            showLoading()
            firestore.addECMember(
                ECMember(
                    id = user.loginEmail,
                    accessLevel = user.accessLevel.name,
                    loginEmail = user.loginEmail,
                    memberId = user.memberId ?: state.value.members.size.toString(),
                    position = user.position,
                    startDate = user.startDate,
                    userId = "",
                    status = user.status.name,
                    firstimeRegistrationCode = user.firstimeRegistrationCode
                )
            )
            hideLoading()
        }.invokeOnCompletion {
            getECMemberList()
        }
    }

    fun addMember(user: User) {
        viewModelScope.launch {
            showLoading()
            firestore.addMember(
                Member(
                    id = user.memberId ?: state.value.members.size.toString(),
                    firstName = user.firstName,
                    lastName = user.lastName,
                    email = user.email,
                    phone = user.phone,
                    countryOfResidence = user.countryOfResidence,
                    joiningDate = user.startDate,
                    dob = user.dob,
                )
            )
            hideLoading()
        }.invokeOnCompletion {
            getMembers()
        }
    }

    @OptIn(ExperimentalCoroutinesApi::class)
    fun verifyEmail(email: String, code: String) {
        if (email.isEmpty() || code.isEmpty()) {
            _event.trySend(MainEvent.RegistrationError("Email and code cannot be empty"))
            return
        }
        viewModelScope.launch {
            showLoading()
            try {
                val ecMembers = async { firestore.getECMembers() }
                awaitAll(ecMembers)
                val user = ecMembers.getCompleted().find { it.loginEmail == email }
                if (user == null) {
                    _event.trySend(MainEvent.RegistrationError("This email is not recognized by our system, please contact SHTC Foundation for support!"))
                } else if (user.status == Status.REGISTRATION_PENDING.name) {
                    if (code == user.firstimeRegistrationCode) {
                        this@MainViewModel.ecMember = user
                        _event.trySend(MainEvent.EmailVerified(email, code, "Email verified"))
                    } else {
                        _event.trySend(MainEvent.RegistrationError("Invalid registration code"))
                    }
                } else {
                    _event.trySend(MainEvent.RegistrationError("This email is already registered, please login or contact SHTC Foundation for support!"))
                }
                hideLoading()
            } catch (e: Exception) {
                _event.trySend(MainEvent.RegistrationError(e.message ?: "Unknown error"))
            }
        }
    }

    fun register(email: String, password: String, confirmPassword: String) {
        if (email.isEmpty() || password.isEmpty() || confirmPassword.isEmpty()) {
            _event.trySend(MainEvent.RegistrationError("Email, password and confirm password cannot be empty"))
            return
        }
        if (password != confirmPassword) {
            _event.trySend(MainEvent.RegistrationError("Passwords do not match"))
            return
        }
        viewModelScope.launch {
            showLoading()
            try {
                authService.register(
                    email = email,
                    password = password
                )
                if (authService.isLoggedIn) {
                    ecMember?.let { ec ->
                        firestore.addECMember(
                            ecMember = ec.copy(status = Status.VERIFICATION_PENDING.name)
                        )
                    }
                    _event.trySend(MainEvent.RegistrationSuccess(email, password))
                }
            } catch (e: Exception) {
                _event.trySend(
                    MainEvent.RegistrationError(
                        e.message ?: "Registration failed, please try again"
                    )
                )
            }
            hideLoading()
        }
    }

    fun login(email: String, password: String) {
        if (email.isEmpty() || password.isEmpty()) {
            _event.trySend(MainEvent.LoginError("Email and password cannot be empty"))
            return
        }
        viewModelScope.launch {
            showLoading()
            try {
                authService.login(
                    email = email,
                    password = password
                )
                if (authService.isLoggedIn) {
                    _event.trySend(MainEvent.LoginSuccess(email, password))
                }
            } catch (e: Exception) {
                _event.trySend(MainEvent.LoginError(e.message ?: "Login failed, please try again"))
            }
            hideLoading()
        }
    }

    @OptIn(ExperimentalCoroutinesApi::class)
    fun addDonation(donation: Donation, oldAmount: Long?, oldStatus: String?) {
        viewModelScope.launch {
            showLoading()
            val addDonationJob = async {
                val id =
                    donation.id.takeIf { it.isNotEmpty() } ?: state.value.donations.size.toString()
                firestore.addDonation(
                    donation.copy(
                        id = id,
                    )
                )
            }
            val accounts = async { firestore.getAccounts() }

            val amount = if (oldAmount != null) {
                donation.amount - oldAmount
            } else {
                donation.amount
            }

//            val status = if (oldStatus != null && oldStatus != donation.status) {
//                if (donation.status == PaymentStatus.PAID.name) {
//                    PaymentStatus.PENDING.name
//                } else {
//                    PaymentStatus.PAID.name
//                }
//            } else {
//                donation.status
//            }

            awaitAll(addDonationJob, accounts)
            val acc = accounts.getCompleted().find { it.id == donation.accountId }
            val balance = if (donation.status == PaymentStatus.PAID.name) {
                acc?.balance?.plus(amount) ?: 0.0
            } else acc?.balance ?: 0.0
            val pendingBalance = if (donation.status == PaymentStatus.PENDING.name) {
                acc?.pending?.plus(amount) ?: 0.0
            } else acc?.pending ?: 0.0

            firestore.updateAccount(
                com.shtcfoundation.data.model.Account(
                    id = acc?.id ?: "",
                    name = acc?.name ?: "",
                    balance = balance,
                    currency = acc?.currency ?: "",
                    country = acc?.country ?: "",
                    pending = pendingBalance,
                )
            )
            hideLoading()
        }.invokeOnCompletion {
            getDonations()
            getAccounts()
        }
    }

    fun addProject(project: Project) {
        viewModelScope.launch {
            showLoading()
            val id = project.id.takeIf { it.isNotEmpty() } ?: state.value.projects.size.toString()
            firestore.addProject(project.copy(id = id))
            hideLoading()
        }.invokeOnCompletion {
            getProjects()
        }
    }

    fun getExpenses() {
        viewModelScope.launch {
            showLoading()
            val expenses = firestore.getExpenses()
            _state.update { it.copy(expenses = expenses) }
            hideLoading()
        }
    }

    @OptIn(ExperimentalCoroutinesApi::class)
    fun addExpense(expense: Expense, oldAmount: Long?) {
        viewModelScope.launch {
            showLoading()
            val addExpenseJob = async {
                val id =
                    expense.id.takeIf { it.isNotEmpty() } ?: state.value.expenses.size.toString()
                firestore.addExpense(expense.copy(id = id))
            }
            val accounts = async { firestore.getAccounts() }

            val amount = if (oldAmount != null) {
                expense.amount - oldAmount
            } else {
                expense.amount
            }

            awaitAll(addExpenseJob, accounts)
            val acc = accounts.getCompleted().find { it.id == expense.fromAccountId }
            val balance = acc?.balance?.minus(amount) ?: 0.0

            firestore.updateAccount(
                com.shtcfoundation.data.model.Account(
                    id = acc?.id ?: "",
                    name = acc?.name ?: "",
                    balance = balance,
                    currency = acc?.currency ?: "",
                    country = acc?.country ?: "",
                    pending = acc?.pending ?: 0.0,
                )
            )
            hideLoading()
        }.invokeOnCompletion {
            getExpenses()
            getAccounts()
        }
    }

    private fun showLoading() {
        _state.update { it.copy(isLoading = true) }
    }

    private fun hideLoading() {
        _state.update { it.copy(isLoading = false) }
    }
}

data class MainState(
    val isLoading: Boolean = false,
    val isLoggedIn: Boolean = false,
    val accounts: List<Account> = emptyList(),
    val user: User? = null,
    val ecMembers: List<User> = emptyList(),
    val donations: List<FullDonation> = emptyList(),
    val members: List<Member> = emptyList(),
    val donors: List<User> = emptyList(),
    val projects: List<Project> = emptyList(),
    val expenses: List<Expense> = emptyList(),
)

sealed interface MainEvent {
    data class LoginSuccess(val email: String, val password: String) : MainEvent
    data class EmailVerified(val email: String, val code: String, val message: String) : MainEvent
    data class LoginError(val error: String) : MainEvent
    data class RegistrationError(val error: String) : MainEvent
    data class RegistrationSuccess(val email: String, val password: String) : MainEvent
}