@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AddDonationBottomSheet(
    bottomSheetState: SheetState,
    donation: Donation? = null,
    accounts: List<Account>,
    donors: List<User>,
    projects: List<Project>,
    ecMembers: List<User>,
    onCancelClicked: () -> Unit,
    onSaveClicked: (donation: Donation, oldAmount: Long?, oldStatus: String?) -> Unit,
) {

    val scope = rememberCoroutineScope()
    val isEditMode = donation != null

    var accountId by remember { mutableStateOf(donation?.accountId ?: "") }
    var amount by remember { mutableStateOf(donation?.amount?.toString() ?: "") }
    var currency by remember { mutableStateOf(donation?.currency ?: "") }
    var donationCountry by remember { mutableStateOf(donation?.donationCountry ?: "") }
    var donorId by remember { mutableStateOf(donation?.donorId ?: "") }
    var frequency by remember { mutableStateOf(donation?.frequency ?: "") }
    var projectId by remember { mutableStateOf(donation?.projectId ?: "") }
    var pledgeDate by remember { mutableStateOf(donation?.pledgeDate ?: "") }
    var paymentDate by remember { mutableStateOf(donation?.paymentDate ?: "") }
    var status by remember { mutableStateOf(donation?.status ?: "") }
    var remark by remember { mutableStateOf(donation?.remarks ?: "") }
    var fundraiserId by remember { mutableStateOf(donation?.fundraiserId ?: "") }
    var isError by remember { mutableStateOf(false) }

    // Bottom Sheet
    ModalBottomSheet(
        shape = RoundedCornerShape(topStart = 16.dp, topEnd = 16.dp),
        content = {
            Box(modifier = Modifier.padding(16.dp)) {
                Surface(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(topStart = 16.dp, topEnd = 16.dp)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .verticalScroll(rememberScrollState())
                    ) {
                        Text(
                            text = if (isEditMode) "Edit Donation" else "Add Donation",
                            style = MaterialTheme.typography.titleLarge,
                            fontWeight = FontWeight(700),
                            color = Color.Black,
                            fontSize = 22.sp,
                            fontFamily = FontFamily.Default,
                            modifier = Modifier.align(Alignment.CenterHorizontally)
                        )

                        SelectableTextField(
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                            value = donors.firstOrNull { it.memberId == donorId }?.fullName ?: "",
                            label = "Donor",
                            dialogTitle = "Select a donor",
                            items = donors.map { it.fullName },
                            onItemSelected = { index, item ->
                                donorId = donors[index].memberId ?: ""
                            }
                        )

                        SelectableTextField(
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                            value = accounts.firstOrNull { it.id == accountId }?.accountType ?: "",
                            label = "Account",
                            dialogTitle = "Select an account",
                            items = accounts.map { it.accountType },
                            onItemSelected = { index, item ->
                                accountId = accounts[index].id
                            }
                        )

                        Row(
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                        ) {
                            OutlinedTextField(
                                value = amount,
                                onValueChange = { amount = it },
                                label = { Text("Amount") },
                                modifier = Modifier.weight(1f),
                                maxLines = 1,
                                keyboardOptions = KeyboardOptions(
                                    keyboardType = KeyboardType.Number,
                                    imeAction = ImeAction.Done
                                )
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            SelectableTextField(
                                modifier = Modifier.weight(1f),
                                value = currency,
                                label = "Currency",
                                dialogTitle = "Select currency",
                                items = Currency.entries.map { it.name },
                                onItemSelected = { index, item ->
                                    currency = item
                                }
                            )
                        }

                        SelectableTextField(
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                            value = frequency,
                            label = "Frequency",
                            dialogTitle = "Select a frequency",
                            items = Frequency.getList(),
                            onItemSelected = { index, item ->
                                frequency = item
                            }
                        )

                        SelectableTextField(
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                            value = projects.firstOrNull { it.id == projectId }?.name ?: "",
                            label = "Project",
                            dialogTitle = "Select a project",
                            items = projects.map { it.name },
                            onItemSelected = { index, item ->
                                projectId = projects[index].id
                            }
                        )

                        SelectableTextField(
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                            value = donationCountry,
                            label = "Country of donation",
                            dialogTitle = "Select a donation country",
                            items = Country.entries.map { it.name },
                            onItemSelected = { index, item ->
                                donationCountry = item
                            }
                        )

                        SelectableTextField(
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                            value = ecMembers.firstOrNull { it.memberId == fundraiserId }?.fullName
                                ?: "",
                            label = "Fundraiser",
                            dialogTitle = "Select a fundraiser",
                            items = ecMembers.map { it.fullName },
                            onItemSelected = { index, item ->
                                fundraiserId = ecMembers[index].memberId ?: ""
                            }
                        )

                        OutlinedTextField(
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                            value = pledgeDate,
                            onValueChange = { pledgeDate = it },
                            label = { Text("Pledge date (dd-mm-yyyy)") },
                            maxLines = 1,
                            keyboardOptions = KeyboardOptions(
                                keyboardType = KeyboardType.Text,
                                imeAction = ImeAction.Done
                            )
                        )

                        OutlinedTextField(
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                            value = paymentDate,
                            onValueChange = { paymentDate = it },
                            label = { Text("Payment date (dd-mm-yyyy)") },
                            maxLines = 1,
                            keyboardOptions = KeyboardOptions(
                                keyboardType = KeyboardType.Text,
                                imeAction = ImeAction.Done
                            )
                        )

                        SelectableTextField(
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                            value = status,
                            label = "Payment status",
                            dialogTitle = "Select payment status",
                            items = PaymentStatus.entries.map { it.name },
                            onItemSelected = { index, item ->
                                status = item
                            }
                        )

                        Spacer(modifier = Modifier.height(24.dp))

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.End
                        ) {
                            OutlinedButton(
                                onClick = {
                                    if (
                                        accountId.isNotEmpty() &&
                                        amount.isNotEmpty() &&
                                        currency.isNotEmpty() &&
                                        donationCountry.isNotEmpty() &&
                                        donorId.isNotEmpty() &&
                                        frequency.isNotEmpty() &&
                                        projectId.isNotEmpty() &&
                                        (pledgeDate.isNotEmpty() || paymentDate.isNotEmpty()) &&
                                        fundraiserId.isNotEmpty()
                                    ) {
                                        isError = false
                                        val amountValue = try {
                                            amount.toLong()
                                        } catch (e: NumberFormatException) {
                                            isError = true
                                            0
                                        }
                                        if (!isError) {
                                            scope.launch { bottomSheetState.hide() }
                                                .invokeOnCompletion {
                                                    onSaveClicked(
                                                        Donation(
                                                            id = donation?.id ?: "",
                                                            accountId = accountId,
                                                            amount = amountValue,
                                                            currency = currency,
                                                            donationCountry = donationCountry,
                                                            donorId = donorId,
                                                            frequency = frequency,
                                                            projectId = projectId,
                                                            pledgeDate = pledgeDate,
                                                            paymentDate = paymentDate,
                                                            fundraiserId = fundraiserId,
                                                            remarks = remark,
                                                            status = status
                                                        ),
                                                        donation?.amount,
                                                        donation?.status,
                                                    )
                                                }
                                        }
                                    } else {
                                        isError = true
                                    }
                                },
                                shape = RoundedCornerShape(50),
                                colors = ButtonDefaults.outlinedButtonColors(
                                    contentColor = Color(
                                        0xFF6750A4
                                    )
                                ),
                                modifier = Modifier.padding(8.dp)
                            ) {
                                Text(
                                    text = "Save",
                                    style = TextStyle(
                                        fontSize = 14.sp,
                                        lineHeight = 20.sp,
                                        fontFamily = FontFamily.Default,
                                        fontWeight = FontWeight(500),
                                        color = Color(0xFF6750A4),
                                        textAlign = TextAlign.Center,
                                        letterSpacing = 0.1.sp
                                    )
                                )
                            }

                            OutlinedButton(
                                onClick = {
                                    scope.launch { bottomSheetState.hide() }.invokeOnCompletion {
                                        onCancelClicked()
                                    }
                                },
                                shape = RoundedCornerShape(50),
                                colors = ButtonDefaults.outlinedButtonColors(
                                    contentColor = Color(
                                        0xFF6750A4
                                    )
                                ),
                                modifier = Modifier.padding(8.dp)
                            ) {
                                Text(
                                    text = "Cancel", style = TextStyle(
                                        fontSize = 14.sp,
                                        lineHeight = 20.sp,
                                        fontFamily = FontFamily.Default,
                                        fontWeight = FontWeight(500),
                                        color = Color(0xFF6750A4),
                                        textAlign = TextAlign.Center,
                                        letterSpacing = 0.1.sp
                                    )
                                )
                            }
                        }
                    }
                }
            }
        },
        sheetState = bottomSheetState,
        onDismissRequest = {
            onCancelClicked()
        }
    )
}

@Composable
fun SelectableTextField(
    modifier: Modifier = Modifier,
    value: String,
    label: String,
    dialogTitle: String,
    items: List<String>,
    onItemSelected: (index: Int, item: String) -> Unit,
) {
    var isDialogVisible by remember { mutableStateOf(false) }

    OutlinedTextField(
        value = value,
        onValueChange = {},
        label = { Text(label) },
        modifier = modifier
            .background(MaterialTheme.colorScheme.background)
            .pointerInput(Unit) {
                detectTapGestures(onTap = {
                    isDialogVisible = true
                })
            },
        readOnly = true,
        enabled = false,
        maxLines = 1,
        colors = OutlinedTextFieldDefaults.colors(
            disabledBorderColor = MaterialTheme.colorScheme.outline,
            disabledContainerColor = MaterialTheme.colorScheme.background,
            disabledTextColor = MaterialTheme.colorScheme.onBackground,
            disabledLabelColor = MaterialTheme.colorScheme.onBackground,
            disabledLeadingIconColor = MaterialTheme.colorScheme.onBackground,
            disabledTrailingIconColor = MaterialTheme.colorScheme.onBackground,
        ),
        trailingIcon = {
            IconButton(
                onClick = { isDialogVisible = true },
                modifier = Modifier.padding(start = 8.dp)
            ) {
                Icon(Icons.Default.Add, contentDescription = "ADD")
            }
        },
    )

    if (isDialogVisible) {
        AlertDialogListItems(
            showDialog = true,
            onDismissRequest = { isDialogVisible = false },
            title = dialogTitle,
            items = items,
            onItemSelected = { index, item ->
                onItemSelected(index, item)
                isDialogVisible = false
            },
        )
    }
}