package com.shtcfoundation.ui.models

enum class PaymentStatus {
    PENDING,
    PAID,
    FAILED;

    companion object {
        fun fromString(value: String): PaymentStatus {
            return when (value) {
                "PENDING" -> PENDING
                "PAID" -> PAID
                "FAILED" -> FAILED
                else -> PENDING
            }
        }
    }
}